func (l *ArcLexer) Sempred(localctx antlr.RuleContext, ruleIndex, predIndex int) bool {
	switch ruleIndex {
	case 68:
		return l.IDENTIFIER_Sempred(localctx, predIndex)

	default:
		panic("No registered predicate for: " + fmt.Sprint(ruleIndex))
	}
}

func (p *ArcLexer) IDENTIFIER_Sempred(localctx antlr.RuleContext, predIndex int) bool {
	switch predIndex {
	case 0:
		return p.dashJoinsIdentifier()

	default:
		panic("No predicate with index: " + fmt.Sprint(predIndex))
	}
}
